module fsm(IN, CLK, RST, MATCH);
    input IN, CLK, RST;
    output reg MATCH;
    localparam IDLE = 0, S1 = 1, S2 = 2, S3 = 3, S4 = 4, S5 = 5;
    reg [2:0] state, next_state;

    always @(*) begin
        case(state)
            IDLE: next_state = IN ? S1 : IDLE;
            S1: next_state = ~IN ? S2 : IDLE;
            S2: next_state = ~IN ? S3 : IDLE;
            S3: next_state = IN ? S4 : IDLE;
            S4: next_state = IN ? S5 : IDLE;
            S5: next_state = IN ? S1 : IDLE;
            default: next_state = IDLE;
        endcase
    end

    always @(posedge CLK or posedge RST) begin
        if (RST) 
            state <= IDLE;
        else
            state <= next_state;
    end

    always @(*) begin
        if (RST)
            MATCH = 0;
        else if (state == S5 && IN)
            MATCH = 1;
        else
            MATCH = 0;
    end
endmodule
